    $choice=(object)['op'=>'choose','id'=>$botId,'nonce'=>ChatStore::uuid(),'step'=>'question','choice'=>0];
    $chosen=$public->process($botKey,$origin,$botToken,$choice);
    $assert($chosen['bot']['state']==='handoff'&&$chosen['handoff']['requestedAt']!==null,'A bot handoff enters the same persisted staff request path.');
    $assert(end($chosen['messages'])['body']==='Connecting you to our team.','Existing chats keep the original published flow snapshot.');
    $assert(count($public->process($botKey,$origin,$botToken,$choice)['messages'])===5,'Choice response loss does not append another visitor answer or bot message.');
    $assert($chosen['messages'][3]['author']==='visitor'&&$chosen['messages'][3]['body']==='Staff help','The selected server-defined answer is visible in the transcript.');
    $changedChoice=clone $choice;$changedChoice->choice=1;
    $deny(fn()=>$public->process($botKey,$origin,$botToken,$changedChoice),'A choice nonce cannot be reused for another answer.');
    $stale=clone $choice;$stale->nonce=ChatStore::uuid();
    $deny(fn()=>$public->process($botKey,$origin,$botToken,$stale),'A new nonce cannot answer a completed question.');
    $startSecond=clone $botStart;$startSecond->nonce=ChatStore::uuid();$startSecond->visitorKey=ChatStore::uuid();$secondToken=bin2hex(random_bytes(32));
    $second=$public->process($botKey,$origin,$secondToken,$startSecond);
    $call(fn()=>$service->process((object)['op'=>'send','id'=>$second['id'],'nonce'=>ChatStore::uuid(),'body'=>'A human is here.']));
    $assert($public->process($botKey,$origin,$secondToken,(object)['op'=>'read','id'=>$second['id']])['bot']['state']==='staff','Staff replies atomically stop automated choices.');
    $deny(fn()=>$public->process($botKey,$origin,$secondToken,(object)['op'=>'choose','id'=>$second['id'],'nonce'=>ChatStore::uuid(),'step'=>'question','choice'=>0]),'A choice racing after staff takeover cannot send a bot response.');
    $startThird=clone $botStart;$startThird->nonce=ChatStore::uuid();$startThird->visitorKey=ChatStore::uuid();$thirdToken=bin2hex(random_bytes(32));
    $third=$public->process($botKey,$origin,$thirdToken,$startThird);
    $thirdIdentity=ChatStore::uuid();$thirdHash=hash('sha256',$a->tenantId."\0".$a->serviceId."\0".$startThird->visitorKey);
    $call(fn()=>$store->execute('INSERT INTO nexa_visitor_identity (id,tenant_id,service_id,visitor_key_hash,contact_id,first_seen_at,last_seen_at) VALUES (?,?,?,?,?,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6))',[$thirdIdentity,$a->tenantId,$a->serviceId,$thirdHash,$contact->getId()]));
    $call(fn()=>$store->execute("INSERT INTO nexa_personalization_identity_proof (tenant_id,service_id,visitor_identity_id,issuer_user_id,contact_id,proof_method,evidence_hash,verification_event_id,verified_at,expires_at) VALUES (?,?,?,?,?,'authenticated_session',?,?,UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 1 HOUR))",[$a->tenantId,$a->serviceId,$thirdIdentity,$admin->getId(),$contact->getId(),hash('sha256','bot-fixture'),ChatStore::uuid()]));
    $call(fn()=>$service->process((object)['op'=>'identify','id'=>$third['id'],'visitorKey'=>$startThird->visitorKey]));
    $deny(fn()=>$public->process($botKey,$origin,$thirdToken,(object)['op'=>'choose','id'=>$third['id'],'nonce'=>ChatStore::uuid(),'step'=>'question','choice'=>0]),'Verified live-chat Do Not Contact restrictions also block bot responses.');
    $assert(count($public->process($botKey,$origin,$thirdToken,(object)['op'=>'read','id'=>$third['id']])['messages'])===3,'A blocked bot response does not persist a partial answer.');
    $call(fn()=>$service->process((object)['op'=>'botSave','id'=>$botWidget['id'],'version'=>3,'enabled'=>false]));
    $assert($public->process($botKey,$origin,$thirdToken,(object)['op'=>'read','id'=>$third['id']])['bot']['state']==='stopped','Disabling a widget bot stops waiting conversations on the next request.');
    $assert(count($call(fn()=>$store->rows("SELECT id FROM nexa_chat_message WHERE tenant_id=? AND service_id=? AND conversation_id=? AND author_kind='bot' AND author_user_id IS NOT NULL",[$a->tenantId,$a->serviceId,$botId])))===0,'Bot messages never impersonate a staff user.');
    echo "Live chat checks passed: $checks (rollback-only).\n";
}catch(Throwable $error){fwrite(STDERR,get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n");throw $error;}
finally{if($tx->isStarted())$tx->rollback();}
